    '.comp-quad-y-label{position:absolute;top:50%;left:-12px;transform:translate(-100%,-50%) rotate(-90deg);transform-origin:right center;font-family:var(--fm);font-size:11px;letter-spacing:2px;text-transform:uppercase;opacity:.55;white-space:nowrap}',
