    '.cust-arch-card::before{content:"";position:absolute;top:0;left:0;width:40px;height:3px;background:var(--accent)}',
    '.cust-arch-num{font-family:var(--fh);font-weight:900;font-size:42px;color:var(--accent);line-height:1;font-style:italic;margin-bottom:14px;opacity:.85}',
